namespace Bdgrz.Compliance.Features.Workforce.Models;

/// <summary>
///     The M0-D06 minimum worker attributes other than identity. <c>ManagerPersonId</c> is a
///     restricted workforce field: single-record reads return it, lists redact it.
///     <c>SponsorPersonId</c> is the accountable internal sponsor an external collaborator needs.
/// </summary>
public sealed record WorkRelationshipTerms(string WorkerType, string LifecycleStatus,
    DateOnly StartDate, DateOnly? EndDate, string? Department, Uuid? ManagerPersonId,
    Uuid? SponsorPersonId, string? EmploymentStatusReason = null);

namespace Bdgrz.Compliance.Features.Workforce.Events;

[Discriminator("bdgrz.workforce.work-relationship.recorded", 1)]
public sealed record WorkRelationshipRecorded(Uuid TenantId, Uuid RelationshipId, Uuid PersonId,
    string SourceWorkerId, WorkRelationshipTerms Terms, ActorReference Actor,
    DateTimeOffset ChangedAt) : DomainEvent;

namespace Bdgrz.Compliance.Features.Workforce.Events;

[Discriminator("bdgrz.workforce.work-relationship.revised", 1)]
public sealed record WorkRelationshipRevised(Uuid TenantId, Uuid RelationshipId, long Revision,
    WorkRelationshipTerms Terms, ActorReference Actor, DateTimeOffset ChangedAt) : DomainEvent;
